# feat: custom path for standalone adapter · Issue #5078 · trpc/trpc
created: 2023-11-21, last updated: 2025-08-21, [Read more](https://github.com/trpc/trpc/issues/5078)

Here's what my tRPC server startup code looks like:
```
import { createHTTPServer } from "@trpc/server/adapters/standalone";
import cors from "cors";
import * as http from "http";
import HttpProxy from "http-proxy";
import { createContext } from "./context";
import { appRouter } from "./routes";
const API_PORT = 3001; // Don't actually send requests to this port.
const API_PREFIX = "/api";
createHTTPServer({
  middleware: cors(),
  router: appRouter,
  createContext,
}).listen(API_PORT);
const proxy = new HttpProxy({});
http
  .createServer((req, res) => {
    if (req.url?.startsWith(API_PREFIX + "/")) {
      req.url = req.url.slice(API_PREFIX.length);
    }
    proxy.web(req, res, { target: `http://localhost:${API_PORT}` });
  })
  .listen(process.env.PORT); // Send your requests to this port.
